    bronze_glasspolishingpad = { name = "Bronast polirna blazinica za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast polirna blazinica za steklo za steklarje." },
    silver_glasspolishingpad = { name = "Srebrn polirna blazinica za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn polirna blazinica za steklo za steklarje." },
    gilded_glasspolishingpad = { name = "Pozlačen polirna blazinica za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen polirna blazinica za steklo za steklarje." },
