    master_glasspolishingpad_atelier = { name = "Mojstrski glasspolishingpad atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasspolishingpad_palace = { name = "Suverena glasspolishingpad palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
