GlassPolishingPadMaker.ironStock=12; GlassPolishingPadMaker.bronzeStock=10; GlassPolishingPadMaker.woodStock=14; GlassPolishingPadMaker.leatherStock=14; GlassPolishingPadMaker.silverStock=8; GlassPolishingPadMaker.goldStock=6; GlassPolishingPadMaker.jewelStock=4; GlassPolishingPadMaker.pearlStock=4
GlassPolishingPadMaker.productStock = {}; GlassPolishingPadMaker.buildings = {}; GlassPolishingPadMaker.maker = nil; GlassPolishingPadMaker.activeMaking = {}; GlassPolishingPadMaker.totalProducts = 0; GlassPolishingPadMaker.dayTimer = 0
function GlassPolishingPadMaker.init() GlassPolishingPadMaker.ironStock=12; GlassPolishingPadMaker.bronzeStock=10; GlassPolishingPadMaker.woodStock=14; GlassPolishingPadMaker.leatherStock=14; GlassPolishingPadMaker.silverStock=8; GlassPolishingPadMaker.goldStock=6; GlassPolishingPadMaker.jewelStock=4; GlassPolishingPadMaker.pearlStock=4; GlassPolishingPadMaker.productStock={}; GlassPolishingPadMaker.buildings={}; GlassPolishingPadMaker.maker=nil; GlassPolishingPadMaker.activeMaking={}; GlassPolishingPadMaker.totalProducts=0; GlassPolishingPadMaker.dayTimer=0; print("[GlassPolishingPadMaker] Royal Glass Polishing Pad Maker System initialized (6 products, 4 buildings)") end
function GlassPolishingPadMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassPolishingPadMaker.maker={name=n or ("Blaziničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blaziničar najet: %s (spretnost: %d)",GlassPolishingPadMaker.maker.name,s),"success") end; return true end
function GlassPolishingPadMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassPolishingPadMaker.build(id) local ok,e=GlassPolishingPadMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassPolishingPadMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassPolishingPadMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassPolishingPadMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassPolishingPadMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassPolishingPadMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassPolishingPadMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassPolishingPadMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassPolishingPadMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassPolishingPadMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassPolishingPadMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassPolishingPadMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassPolishingPadMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassPolishingPadMaker.buildings==0 then return false,"Potrebna blazinična delavnica" end; if not GlassPolishingPadMaker.maker then return false,"Potreben blaziničar" end; return true end
function GlassPolishingPadMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassPolishingPadMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassPolishingPadMaker.ironStock=GlassPolishingPadMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassPolishingPadMaker.bronzeStock=GlassPolishingPadMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassPolishingPadMaker.woodStock=GlassPolishingPadMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassPolishingPadMaker.leatherStock=GlassPolishingPadMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassPolishingPadMaker.silverStock=GlassPolishingPadMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassPolishingPadMaker.goldStock=GlassPolishingPadMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassPolishingPadMaker.jewelStock=GlassPolishingPadMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassPolishingPadMaker.pearlStock=GlassPolishingPadMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassPolishingPadMaker.maker then t=math.max(1,t-math.floor(GlassPolishingPadMaker.maker.skill/13)) end; table.insert(GlassPolishingPadMaker.activeMaking,{id="glasspolishingpad_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassPolishingPadMaker.completeMaking(m) local q=1.0+(GlassPolishingPadMaker.getQualityBonus()/100); if GlassPolishingPadMaker.maker then q=q+(GlassPolishingPadMaker.maker.skill/140) end; q=math.min(2.5,q); GlassPolishingPadMaker.productStock[m.productType]=(GlassPolishingPadMaker.productStock[m.productType] or 0)+m.quantity; GlassPolishingPadMaker.totalProducts=GlassPolishingPadMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassPolishingPadMaker.maker then GlassPolishingPadMaker.maker.itemsMade=GlassPolishingPadMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassPolishingPadMaker.maker.skill=math.min(100,GlassPolishingPadMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Blazinica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasspolishingpad.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassPolishingPadMaker.update(dt) if not _G.state then return end; GlassPolishingPadMaker.dayTimer=GlassPolishingPadMaker.dayTimer+dt; if GlassPolishingPadMaker.dayTimer>=30 then GlassPolishingPadMaker.dayTimer=0; for i=#GlassPolishingPadMaker.activeMaking,1,-1 do local m=GlassPolishingPadMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassPolishingPadMaker.completeMaking(m); table.remove(GlassPolishingPadMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassPolishingPadMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassPolishingPadMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassPolishingPadMaker.getStats() return {ironStock=GlassPolishingPadMaker.ironStock,bronzeStock=GlassPolishingPadMaker.bronzeStock,woodStock=GlassPolishingPadMaker.woodStock,leatherStock=GlassPolishingPadMaker.leatherStock,silverStock=GlassPolishingPadMaker.silverStock,goldStock=GlassPolishingPadMaker.goldStock,jewelStock=GlassPolishingPadMaker.jewelStock,pearlStock=GlassPolishingPadMaker.pearlStock,productStock=GlassPolishingPadMaker.productStock,numBuildings=#GlassPolishingPadMaker.buildings,hasMaker=GlassPolishingPadMaker.maker~=nil,makerName=GlassPolishingPadMaker.maker and GlassPolishingPadMaker.maker.name or "—",makerSkill=GlassPolishingPadMaker.maker and GlassPolishingPadMaker.maker.skill or 0,activeMaking=#GlassPolishingPadMaker.activeMaking,totalProducts=GlassPolishingPadMaker.totalProducts} end
return GlassPolishingPadMaker
